import "core-js/modules/es.array.push.js";
import axios from 'axios';
export default {
  data() {
    return {
      profileForm: {
        username: '',
        first_name: '',
        last_name: '',
        email: ''
      }
    };
  },
  mounted() {
    this.fetchUserDetails();
  },
  methods: {
    async fetchUserDetails() {
      try {
        const response = await axios.get('/users/api/profile/');
        const userInfo = response.data.user_info;
        userInfo.forEach(item => {
          const key = item.label.toLowerCase().replace(' ', '_');
          if (key in this.profileForm) {
            this.profileForm[key] = item.value;
          }
        });
      } catch (error) {
        console.error('Error fetching user details:', error);
      }
    },
    async saveProfile() {
      try {
        await axios.post('/users/api/profile/edit/', this.profileForm);
        this.$router.push('/profile');
      } catch (error) {
        console.error('Error saving profile:', error);
      }
    },
    cancel() {
      this.$router.push('/profile');
    }
  }
};
